function:mom_wms.guard_count_plan_359:
DECLARE lock_key text; was_active boolean:=false; now_active boolean;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.stock_freeze_mode='FREEZE_COUNT' THEN
   RAISE EXCEPTION '冻结盘点计划须保留历史；未录入计划请受控逻辑删除，已录入计划请作废';
  END IF;
  RETURN OLD;
 END IF;
 IF NEW.stock_freeze_mode IS NULL OR NEW.tenant_id IS NULL OR NEW.tenant_id<=0
  OR nullif(btrim(NEW.factory_code),'') IS NULL
  OR nullif(btrim(NEW.warehouse_code),'') IS NULL THEN
  RAISE EXCEPTION '盘点计划冻结模式或组织仓库范围不完整';
 END IF;
 IF NEW.stock_freeze_mode='FREEZE_COUNT'
  AND current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION '冻结盘点计划状态变更要求READ COMMITTED事务';
 END IF;
 IF TG_OP='INSERT' AND NEW.stock_freeze_mode='FREEZE_COUNT'
  AND (NEW.status IS DISTINCT FROM '0' OR NEW.handle_state IS DISTINCT FROM '0'
   OR NEW.del_flag IS DISTINCT FROM '0') THEN
  RAISE EXCEPTION '冻结盘点计划必须从待实盘状态创建';
 END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.tenant_id,NEW.factory_code,NEW.warehouse_code,NEW.stock_freeze_mode)
   IS DISTINCT FROM ROW(OLD.tenant_id,OLD.factory_code,OLD.warehouse_code,OLD.stock_freeze_mode) THEN
   RAISE EXCEPTION '盘点计划创建后不能修改组织、仓库或冻结模式';
  END IF;
  was_active:=coalesce(OLD.stock_freeze_mode='FREEZE_COUNT' AND OLD.status='0'
   AND OLD.handle_state='0' AND OLD.del_flag='0',false);
 END IF;
 now_active:=coalesce(NEW.stock_freeze_mode='FREEZE_COUNT' AND NEW.status='0'
  AND NEW.handle_state='0' AND NEW.del_flag='0',false);
 IF TG_OP='UPDATE' AND now_active AND NOT was_active THEN
  RAISE EXCEPTION '已结束或删除的冻结盘点计划不能重新开启';
 END IF;
 IF was_active OR now_active THEN
  IF TG_OP='INSERT' THEN
   lock_key:='WMS_INVENTORY_FREEZE|'||NEW.tenant_id||'|'||NEW.factory_code||'|'||NEW.warehouse_code;
  ELSE
   lock_key:='WMS_INVENTORY_COUNT_STATE|'||NEW.tenant_id||'|'||NEW.id;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(lock_key,0));
 END IF;
 IF TG_OP='UPDATE' AND was_active AND NOT now_active THEN
  IF NEW.status='1' AND NEW.handle_state='0' AND NEW.del_flag='0' THEN
   IF NOT EXISTS(SELECT 1 FROM mom_wms.wms_inside_inventory_plan_detail d
    WHERE d.plan_id=NEW.id AND d.tenant_id=NEW.tenant_id
     AND d.factory_code=NEW.factory_code AND d.warehouse_code=NEW.warehouse_code
     AND d.del_flag='0') OR EXISTS(
    SELECT 1 FROM mom_wms.wms_inside_inventory_plan_detail d
     WHERE d.plan_id=NEW.id AND d.tenant_id=NEW.tenant_id
      AND d.factory_code=NEW.factory_code AND d.warehouse_code=NEW.warehouse_code
      AND d.del_flag='0' AND (d.status IS DISTINCT FROM '1'
       OR d.inventory_num IS NULL OR d.pl_status IS DISTINCT FROM '0')) THEN
    RAISE EXCEPTION '盘点明细尚未全部实盘录入，不能释放库存冻结';
   END IF;
  ELSIF NEW.status='2' AND NEW.handle_state='2' AND NEW.del_flag='0' THEN
   -- 330节的作废审计约束继续核验请求号、原因、操作者和时间。
   NULL;
  ELSIF NEW.status='0' AND NEW.handle_state='0' AND NEW.del_flag='1' THEN
   IF NOT EXISTS(SELECT 1 FROM mom_wms.wms_inside_inventory_plan_detail d
    WHERE d.plan_id=NEW.id AND d.tenant_id=NEW.tenant_id
     AND d.factory_code=NEW.factory_code AND d.warehouse_code=NEW.warehouse_code) OR EXISTS(
    SELECT 1 FROM mom_wms.wms_inside_inventory_plan_detail d
     WHERE d.plan_id=NEW.id AND d.tenant_id=NEW.tenant_id
      AND d.factory_code=NEW.factory_code AND d.warehouse_code=NEW.warehouse_code
      AND (d.status IS DISTINCT FROM '0' OR d.pl_status IS DISTINCT FROM '0'
       OR d.inventory_num IS NOT NULL)) THEN
    RAISE EXCEPTION '已有实盘或处理记录的冻结计划不能删除，请作废';
   END IF;
  ELSE
   RAISE EXCEPTION '冻结盘点只能通过完成实盘、作废或删除未录入计划释放';
  END IF;
 END IF;
 RETURN NEW;
END

function:mom_wms.guard_count_stock_359:
DECLARE scope_row record;
BEGIN
 IF TG_OP='TRUNCATE' THEN
  RAISE EXCEPTION '实时库存禁止TRUNCATE，盘点冻结范围无法逐行校验';
 END IF;
 IF TG_OP='INSERT' THEN
  PERFORM mom_wms.assert_count_scope_open_359(NEW.tenant_id,NEW.factory_code,
   NEW.warehouse_code,NEW.site_code,NEW.mat_code,NEW.mat_batch);
  RETURN NEW;
 END IF;
 IF TG_OP='DELETE' THEN
  PERFORM mom_wms.assert_count_scope_open_359(OLD.tenant_id,OLD.factory_code,
   OLD.warehouse_code,OLD.site_code,OLD.mat_code,OLD.mat_batch);
  RETURN OLD;
 END IF;
 -- 移库和批次变更必须同时检查来源及目标；固定顺序减少多仓事务锁互等。
 FOR scope_row IN
  SELECT DISTINCT s.tenant_id,s.factory_code,s.warehouse_code,s.site_code,s.mat_code,s.mat_batch
   FROM (VALUES
    (OLD.tenant_id,OLD.factory_code,OLD.warehouse_code,OLD.site_code,OLD.mat_code,OLD.mat_batch),
    (NEW.tenant_id,NEW.factory_code,NEW.warehouse_code,NEW.site_code,NEW.mat_code,NEW.mat_batch)
   ) s(tenant_id,factory_code,warehouse_code,site_code,mat_code,mat_batch)
   ORDER BY s.tenant_id,s.factory_code,s.warehouse_code,s.site_code,s.mat_code,s.mat_batch
 LOOP
  PERFORM mom_wms.assert_count_scope_open_359(scope_row.tenant_id,scope_row.factory_code,
   scope_row.warehouse_code,scope_row.site_code,scope_row.mat_code,scope_row.mat_batch);
 END LOOP;
 RETURN NEW;
END

function:mom_wms.guard_count_detail_359:
DECLARE plan_scope record; lock_key text;
BEGIN
 IF TG_OP='TRUNCATE' THEN
  RAISE EXCEPTION '盘点明细禁止TRUNCATE，冻结范围和实盘历史必须保留';
 END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(OLD.plan_id,OLD.tenant_id,OLD.factory_code,OLD.warehouse_code,
   OLD.site_code,OLD.mat_code,OLD.mat_batch,OLD.del_flag)
   IS NOT DISTINCT FROM ROW(NEW.plan_id,NEW.tenant_id,NEW.factory_code,
    NEW.warehouse_code,NEW.site_code,NEW.mat_code,NEW.mat_batch,NEW.del_flag) THEN
   SELECT p.tenant_id,p.factory_code,p.warehouse_code,p.stock_freeze_mode,
          p.status,p.handle_state,p.del_flag INTO plan_scope
    FROM mom_wms.wms_inside_inventory_plan p
    WHERE p.id=OLD.plan_id AND p.tenant_id=OLD.tenant_id
     AND p.factory_code=OLD.factory_code AND p.warehouse_code=OLD.warehouse_code;
   IF FOUND AND plan_scope.stock_freeze_mode='FREEZE_COUNT' THEN
    IF current_setting('transaction_isolation')<>'read committed' THEN
     RAISE EXCEPTION '冻结盘点明细实盘变更要求READ COMMITTED事务';
    END IF;
    lock_key:='WMS_INVENTORY_COUNT_STATE|'||plan_scope.tenant_id||'|'||OLD.plan_id;
    PERFORM pg_advisory_xact_lock(hashtextextended(lock_key,0));
    SELECT p.status,p.handle_state,p.del_flag INTO plan_scope
     FROM mom_wms.wms_inside_inventory_plan p
     WHERE p.id=OLD.plan_id AND p.tenant_id=OLD.tenant_id
      AND p.factory_code=OLD.factory_code AND p.warehouse_code=OLD.warehouse_code;
    IF NOT FOUND OR NEW.current_number IS DISTINCT FROM OLD.current_number THEN
     RAISE EXCEPTION '冻结盘点账面快照不可改写';
    END IF;
    IF plan_scope.status='1' AND (NEW.status IS DISTINCT FROM '1' OR NEW.inventory_num IS NULL) THEN
     RAISE EXCEPTION '已完成实盘的明细不能撤销录入或清空实盘数量';
    END IF;
    IF plan_scope.status='0' AND NEW.pl_status IS DISTINCT FROM '0' THEN
     RAISE EXCEPTION '实盘未完成前不能提前处理损益';
    END IF;
    IF (plan_scope.status='2' OR plan_scope.del_flag<>'0')
     AND ROW(NEW.status,NEW.inventory_num,NEW.pl_status)
      IS DISTINCT FROM ROW(OLD.status,OLD.inventory_num,OLD.pl_status) THEN
     RAISE EXCEPTION '已作废或删除的冻结盘点明细不可改写';
    END IF;
   END IF;
   RETURN NEW;
  END IF;
 END IF;
 IF TG_OP='UPDATE' OR TG_OP='DELETE' THEN
  SELECT p.stock_freeze_mode,p.del_flag INTO plan_scope
   FROM mom_wms.wms_inside_inventory_plan p
   WHERE p.id=OLD.plan_id AND p.tenant_id=OLD.tenant_id
    AND p.factory_code=OLD.factory_code AND p.warehouse_code=OLD.warehouse_code;
  IF TG_OP='UPDATE' AND FOUND AND plan_scope.stock_freeze_mode='FREEZE_COUNT'
   AND plan_scope.del_flag='1' THEN
   IF OLD.del_flag='0' AND NEW.del_flag='1'
    AND ROW(NEW.plan_id,NEW.tenant_id,NEW.factory_code,NEW.warehouse_code,
     NEW.site_code,NEW.mat_code,NEW.mat_batch,NEW.current_number,
     NEW.status,NEW.inventory_num,NEW.pl_status)
     IS NOT DISTINCT FROM ROW(OLD.plan_id,OLD.tenant_id,OLD.factory_code,OLD.warehouse_code,
      OLD.site_code,OLD.mat_code,OLD.mat_batch,OLD.current_number,
      OLD.status,OLD.inventory_num,OLD.pl_status)
    AND OLD.status='0' AND OLD.pl_status='0' AND OLD.inventory_num IS NULL THEN
    RETURN NEW;
   END IF;
   RAISE EXCEPTION '已逻辑删除的冻结盘点仅允许清理未录入明细';
  END IF;
  IF FOUND AND plan_scope.stock_freeze_mode='FREEZE_COUNT' AND plan_scope.del_flag='0' THEN
   RAISE EXCEPTION '冻结盘点明细范围不可更改；未录入计划请先受控删除计划';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 END IF;
 IF TG_OP='INSERT' OR TG_OP='UPDATE' THEN
  SELECT p.tenant_id,p.factory_code,p.warehouse_code,p.stock_freeze_mode,
         p.status,p.handle_state,p.del_flag INTO plan_scope
   FROM mom_wms.wms_inside_inventory_plan p
   WHERE p.id=NEW.plan_id AND p.tenant_id=NEW.tenant_id
    AND p.factory_code=NEW.factory_code AND p.warehouse_code=NEW.warehouse_code;
  IF NOT FOUND THEN RAISE EXCEPTION '盘点明细缺少相同组织仓库的计划'; END IF;
  IF plan_scope.stock_freeze_mode='FREEZE_COUNT' THEN
   IF current_setting('transaction_isolation')<>'read committed' THEN
    RAISE EXCEPTION '盘点冻结范围变更要求READ COMMITTED事务';
   END IF;
   lock_key:='WMS_INVENTORY_COUNT_STATE|'||plan_scope.tenant_id||'|'||NEW.plan_id;
   PERFORM pg_advisory_xact_lock(hashtextextended(lock_key,0));
   lock_key:='WMS_INVENTORY_FREEZE|'||plan_scope.tenant_id||'|'
    ||plan_scope.factory_code||'|'||plan_scope.warehouse_code;
   PERFORM pg_advisory_xact_lock(hashtextextended(lock_key,0));
   SELECT p.status,p.handle_state,p.del_flag INTO plan_scope
    FROM mom_wms.wms_inside_inventory_plan p
    WHERE p.id=NEW.plan_id AND p.tenant_id=NEW.tenant_id
     AND p.factory_code=NEW.factory_code AND p.warehouse_code=NEW.warehouse_code;
   IF NOT FOUND OR plan_scope.status IS DISTINCT FROM '0'
    OR plan_scope.handle_state IS DISTINCT FROM '0'
    OR plan_scope.del_flag IS DISTINCT FROM '0' THEN
    RAISE EXCEPTION '冻结盘点已经结束，不能再新增明细范围';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END

function:mom_wms.guard_org_transfer_bill:
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION '组织调拨业务凭证不可物理删除'; END IF;
 IF ROW(NEW.tenant_id,NEW.id,NEW.bill_no,NEW.source_policy_id,NEW.target_policy_id,NEW.source_factory_code,
   NEW.source_warehouse_code,NEW.source_company_code,NEW.target_factory_code,NEW.target_warehouse_code,NEW.target_company_code,NEW.created_by,NEW.created_by_id)
 IS DISTINCT FROM ROW(OLD.tenant_id,OLD.id,OLD.bill_no,OLD.source_policy_id,OLD.target_policy_id,OLD.source_factory_code,
   OLD.source_warehouse_code,OLD.source_company_code,OLD.target_factory_code,OLD.target_warehouse_code,OLD.target_company_code,OLD.created_by,OLD.created_by_id)
 OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION '组织调拨身份不可重绑定，版本须连续推进'; END IF;
 RETURN NEW;
END;

function:mom_wms.guard_org_transfer_line:
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION '组织调拨原始行不可删除'; END IF;
 IF ROW(NEW.tenant_id,NEW.id,NEW.bill_id,NEW.source_stock_id,NEW.quantity,NEW.source_snapshot)
 IS DISTINCT FROM ROW(OLD.tenant_id,OLD.id,OLD.bill_id,OLD.source_stock_id,OLD.quantity,OLD.source_snapshot)
 OR NEW.received_quantity<OLD.received_quantity OR NEW.returned_quantity<OLD.returned_quantity OR NEW.exception_quantity<OLD.exception_quantity
 OR (OLD.issue_flow_id IS NOT NULL AND ROW(NEW.issue_flow_id,NEW.issue_snapshot) IS DISTINCT FROM ROW(OLD.issue_flow_id,OLD.issue_snapshot)) THEN
   RAISE EXCEPTION '组织调拨来源不可改写，已确认数量不能减少';
 END IF;
 RETURN NEW;
END;

function:mom_wms.guard_org_transfer_poli:
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION '库存组织绑定不可删除，只能停用'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(CONCAT('WMS_ORG_TRANSFER:',NEW.tenant_id,':POLICY:',NEW.factory_code),0));
 IF NEW.enabled THEN
  PERFORM 1 FROM mom_mdm.mdm_warehouse WHERE tenant_id=NEW.tenant_id AND factory_code=NEW.factory_code
   AND warehouse_code=NEW.warehouse_code AND status=true AND del_flag='0' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION '合作库存组织只能发布启用的实际仓库'; END IF;
 END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.tenant_id,NEW.factory_code,NEW.warehouse_code,NEW.company_code)
   IS DISTINCT FROM ROW(OLD.tenant_id,OLD.factory_code,OLD.warehouse_code,OLD.company_code) THEN
   RAISE EXCEPTION '库存组织公司、工厂和仓库绑定不可重定义';
 END IF;
 IF EXISTS(SELECT 1 FROM mom_wms.wms_org_transfer_policy p WHERE p.tenant_id=NEW.tenant_id
   AND p.factory_code=NEW.factory_code AND p.company_code<>NEW.company_code) THEN
   RAISE EXCEPTION '同一工厂的库存组织公司必须一致';
 END IF;
 RETURN NEW;
END;

function:mom_wms.assert_count_scope_open:
DECLARE plan_id bigint; lock_key text;
BEGIN
 IF p_tenant IS NULL OR p_tenant<=0 OR nullif(btrim(p_factory),'') IS NULL
  OR nullif(btrim(p_warehouse),'') IS NULL OR nullif(btrim(p_site),'') IS NULL
  OR nullif(btrim(p_material),'') IS NULL THEN
  RAISE EXCEPTION '实时库存写入范围不完整，不能校验盘点冻结';
 END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION '盘点冻结守卫要求库存写入使用READ COMMITTED事务';
 END IF;
 -- 另用冻结锁；动态盘点只占用计划重叠锁，不暂停仓库作业。
 lock_key:='WMS_INVENTORY_FREEZE|'||p_tenant||'|'||p_factory||'|'||p_warehouse;
 IF NOT pg_try_advisory_xact_lock(hashtextextended(lock_key,0)) THEN
  RAISE EXCEPTION '仓库盘点范围正在建立或释放，请稍后重试库存作业';
 END IF;
 SELECT p.id INTO plan_id FROM mom_wms.wms_inside_inventory_plan p
  JOIN mom_wms.wms_inside_inventory_plan_detail d
   ON d.plan_id=p.id AND d.tenant_id=p.tenant_id AND d.factory_code=p.factory_code
    AND d.warehouse_code=p.warehouse_code AND d.del_flag='0'
  WHERE p.tenant_id=p_tenant AND p.factory_code=p_factory
   AND p.warehouse_code=p_warehouse AND p.stock_freeze_mode='FREEZE_COUNT'
   AND p.status='0' AND p.handle_state='0' AND p.del_flag='0'
   AND d.site_code=p_site AND d.mat_code=p_material
   AND (nullif(btrim(d.mat_batch),'') IS NULL
    OR btrim(d.mat_batch)=btrim(coalesce(p_batch,'')))
  LIMIT 1;
 IF plan_id IS NOT NULL THEN
  RAISE EXCEPTION '盘点计划%实盘期间冻结该物料库位批次，请先完成实盘或作废',plan_id;
 END IF;
END

function:mom_wms.guard_mobile_transfer_c:
DECLARE payload jsonb;
BEGIN
	IF TG_OP <> 'INSERT' THEN
		RAISE EXCEPTION '接收永久取消回执不可改写或删除';
	END IF;
	PERFORM pg_advisory_xact_lock(hashtextextended(CONCAT('WMS_TRANSFER_RECEIPT:',NEW.tenant_id,':',NEW.request_id),0));
	IF EXISTS (SELECT 1 FROM mom_wms.wms_transfer_receipt WHERE tenant_id=NEW.tenant_id AND request_id=NEW.request_id) THEN
		RAISE EXCEPTION '原接收已存在业务凭证，不可取消为未执行';
	END IF;
	payload := NEW.request_snapshot::jsonb;
	IF jsonb_typeof(payload) IS DISTINCT FROM 'object'
		OR payload->>'billId' IS DISTINCT FROM NEW.allocation_bill_id::text
		OR jsonb_typeof(payload->'final') IS DISTINCT FROM 'boolean'
		OR jsonb_typeof(payload->'lines') IS DISTINCT FROM 'array' THEN
		RAISE EXCEPTION '接收取消回执原文与单据不一致';
	END IF;
	IF jsonb_array_length(payload->'lines') NOT BETWEEN 1 AND 500 THEN
		RAISE EXCEPTION '接收取消明细数量不合法';
	END IF;
	RETURN NEW;
END;

function:mom_wms.guard_org_transfer_immu:
BEGIN
 RAISE EXCEPTION '组织调拨永久回执与实物效果不可改写或删除';
END;

function:mom_wms.org_transfer_warehouse_:
BEGIN
 IF TG_OP='UPDATE' AND NEW.status=false AND OLD.status IS DISTINCT FROM NEW.status THEN
  UPDATE mom_wms.wms_org_transfer_policy SET enabled=false,version=version+1,updated_time=CURRENT_TIMESTAMP
   WHERE tenant_id=NEW.tenant_id AND factory_code=NEW.factory_code AND warehouse_code=NEW.warehouse_code AND enabled=true;
 END IF;
 IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND (NEW.del_flag='1' OR ROW(NEW.tenant_id,NEW.factory_code,NEW.warehouse_code) IS DISTINCT FROM ROW(OLD.tenant_id,OLD.factory_code,OLD.warehouse_code))) THEN
  IF EXISTS(SELECT 1 FROM mom_wms.wms_org_transfer_bill WHERE tenant_id=OLD.tenant_id AND
    ((source_factory_code=OLD.factory_code AND source_warehouse_code=OLD.warehouse_code)
      OR (target_factory_code=OLD.factory_code AND target_warehouse_code=OLD.warehouse_code))) THEN
   RAISE EXCEPTION '仓库存在组织调拨历史，不可删除或重绑定';
  END IF;
  IF EXISTS(SELECT 1 FROM mom_wms.wms_org_transfer_policy WHERE tenant_id=OLD.tenant_id AND factory_code=OLD.factory_code
    AND warehouse_code=OLD.warehouse_code AND enabled=true) THEN RAISE EXCEPTION '先停用合作库存组织再删除仓库'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;

function:mom_wms.guard_allocation_cancel:
BEGIN
	IF TG_OP = 'DELETE' THEN
		IF NULLIF(trim(OLD.request_id), '') IS NOT NULL THEN
			RAISE EXCEPTION '调拨原请求业务凭证不可物理删除';
		END IF;
		RETURN OLD;
	END IF;
	IF TG_OP = 'UPDATE' AND NULLIF(trim(OLD.request_id), '') IS NOT NULL
		AND ROW(NEW.tenant_id, NEW.request_id) IS DISTINCT FROM ROW(OLD.tenant_id, OLD.request_id) THEN
		RAISE EXCEPTION '调拨原请求租户与永久请求号不可重绑定';
	END IF;
	IF NULLIF(trim(NEW.request_id), '') IS NOT NULL THEN
		PERFORM pg_advisory_xact_lock(hashtextextended(CONCAT('WMS_AGENT_TRANSFER:MOBILE_REQUEST:', NEW.tenant_id, ':', NEW.request_id), 0));
		IF EXISTS (SELECT 1 FROM mom_wms.wms_mobile_allocation_cancel_receipt
			WHERE tenant_id=NEW.tenant_id AND request_id=NEW.request_id) THEN
			RAISE EXCEPTION '原即时调拨请求已撤销，禁止重放执行';
		END IF;
	END IF;
	RETURN NEW;
END;

function:mom_wms.guard_mobile_allocation:
DECLARE payload jsonb;
BEGIN
	IF TG_OP <> 'INSERT' THEN
		RAISE EXCEPTION '即时调拨永久撤销回执不可改写或删除';
	END IF;
	PERFORM pg_advisory_xact_lock(hashtextextended(CONCAT('WMS_AGENT_TRANSFER:MOBILE_REQUEST:', NEW.tenant_id, ':', NEW.request_id), 0));
	IF EXISTS (SELECT 1 FROM mom_wms.wms_allocation_bill
		WHERE tenant_id=NEW.tenant_id AND request_id=NEW.request_id) THEN
		RAISE EXCEPTION '原调拨已有业务单，不得再封存为未执行撤销';
	END IF;
	payload := NEW.request_snapshot::jsonb;
	IF jsonb_typeof(payload) IS DISTINCT FROM 'object'
		OR payload->>'factory' IS DISTINCT FROM NEW.factory_code
		OR payload->>'sourceWarehouse' IS DISTINCT FROM NEW.warehouse_code
		OR payload->>'billNo' IS DISTINCT FROM NEW.bill_no
		OR jsonb_typeof(payload->'quantity') IS DISTINCT FROM 'number'
		OR COALESCE((payload->>'quantity')::numeric, 0) <= 0 THEN
		RAISE EXCEPTION '即时调拨撤销原文与身份或数量不一致';
	END IF;
	RETURN NEW;
END;

function:mom_wms.guard_transfer_receipt_:
BEGIN
	IF TG_OP = 'DELETE' THEN
		RAISE EXCEPTION '接收原始业务凭证不可物理删除';
	END IF;
	IF TG_OP = 'UPDATE' AND ROW(NEW.tenant_id,NEW.request_id,NEW.allocation_bill_id,NEW.factory_code,NEW.receiver_code,NEW.request_snapshot)
		IS DISTINCT FROM ROW(OLD.tenant_id,OLD.request_id,OLD.allocation_bill_id,OLD.factory_code,OLD.receiver_code,OLD.request_snapshot) THEN
		RAISE EXCEPTION '接收原始身份、单据、原号和原文不可重绑定';
	END IF;
	PERFORM pg_advisory_xact_lock(hashtextextended(CONCAT('WMS_TRANSFER_RECEIPT:',NEW.tenant_id,':',NEW.request_id),0));
	IF EXISTS (SELECT 1 FROM mom_wms.wms_mobile_transfer_cancel_receipt WHERE tenant_id=NEW.tenant_id AND request_id=NEW.request_id) THEN
		RAISE EXCEPTION '原接收请求已取消，禁止重放入库';
	END IF;
	RETURN NEW;
END;
